  function workPreserved(s){const a=s.account,q=a.queues.find(q=>q.name==='email-work');return q?.queueId==='original-work'&&q.messages.length===1&&q.messages[0].messageId==='original-email-101'&&q.messages[0].body===initial.queues[0].messages[0].body&&!q.isFifo&&q.visibilityTimeout===120&&Object.entries(initial.queues[0].attributes).every(([k,v])=>q.attributes[k]===v)&&fn(s)?.fixtureId==='original-email-function'&&fn(s).roleName==='sale-email-role'&&fn(s).timeout===10&&fn(s).runtime==='python3.12'&&fn(s).handler==='app.handler'&&same(a.roles,initial.roles)&&a.eventSourceMappings.length===1&&mapping(s)?.functionName==='sale-email'&&mapping(s).eventSourceArn===arn('email-work')&&mapping(s).batchSize===10&&same(mapping(s).responseTypes,['ReportBatchItemFailures']);}
